; ============================================================
; NTC program - generated by NTC BASIC (VB style BASIC to NTC)
; platform: cpcfw (Amstrad CPC - firmware text and keys), starts in normal mode
; ============================================================

			DEVICE AMSTRADCPC6128		; for SAVEAMSDOS at the end
			org #0040

NTC_TERM	equ 0		; Option Terminal: 0 none, 1 VT52, 2 ANSI (CP/M)
NTC_STRMAX	equ 255		; the longest string (library buffers, temps)
NTC_MEMBANKS	equ 64		; Option Memory: the most 64K banks the Memory class looks for
NTC_ROMENABLE	equ 0		; Option RomEnable (cpcfw, cpcmin): the start code starts the ROMs

ntc_start:
			di
			call ntc_rj_find		; Library: ROM - find the ROM, patch the jump block
			jr nc, ntc_rj_ok
			ei
			ret				; no ROM (the message is shown): back to the caller
ntc_rj_ok:
			ld hl, ntc_rj_exit
			push hl			; End comes back here: the caller's ROM selection again
			ld (ntc_csp), sp
			ld a, 1
			ld (ntc_nmode), a		; normal mode: waits let interrupts in
			ld sp, main_thread
			ret

; ============================================================
; Main Thread
; ============================================================

main_thread:
			dw kw_bssinit, ntc_bss, ntc_bss_size		; the arrays: do they fit, clear them

			; 3: n = 1000
			dw kw_ltov, 1000, var_n

			; 4: For i = 2 To n : s(i) = 1 : Next
			dw kw_ltov, 2, var_i
			dw kw_vtov, var_n, for1_l
			dw kw_forupv_n, var_i, for1_l, for1_e
for1_t:
			dw kw_asetl, arr_s, var_i, 1
			dw kw_next1v_n, var_i, for1_l, for1_t
for1_e:

			; 5: i = 2
			dw kw_ltov, 2, var_i

			; 6: While i * i <= n
			dw wh2_c_go
wh2_t:

			; 7: If s(i) Then
			dw kw_aget, arr_s, var_i, tmp0
			dw kw_goto_ifzero_n, tmp0, if3_1

			; 8: For j = i * i To n Step i : s(j) = 0 : Next
			dw kw_mulvv, var_i, var_i, var_j
			dw kw_vtov, var_n, for4_l
			dw kw_vtov, var_i, for4_s
			dw kw_forentry_n, var_j, for4_s, for4_l, for4_e
for4_t:
			dw kw_asetl, arr_s, var_j, 0
			dw kw_fornext_n, var_j, for4_s, for4_l, for4_t
for4_e:

			; 9: End If
if3_1:

			; 10: i = i + 1
			dw kw_inc, var_i

			; 11: Wend
wh2_c:
			dw kw_mulvv, var_i, var_i, tmp0
			dw kw_scplevv, tmp0, var_n
			dw kw_goto_iftrue_n, wh2_t
wh2_e:

			; 12: c = 0
			dw kw_ztov, var_c

			; 13: For i = 2 To n
			dw kw_ltov, 2, var_i
			dw kw_vtov, var_n, for5_l
			dw kw_forupv_n, var_i, for5_l, for5_e
for5_t:

			; 14: If s(i) Then Print i; " "; : c = c + 1
			dw kw_aget, arr_s, var_i, tmp0
			dw kw_goto_ifzero_n, tmp0, if6_1
			dw kw_printint, var_i
			dw kw_printstrvar, str0
			dw kw_inc, var_c
if6_1:

			; 15: Next
			dw kw_next1v_n, var_i, for5_l, for5_t
for5_e:

			; 16: Print : Print c; " primes"
			dw kw_printnl
			dw kw_printint, var_c
			dw kw_printstrvar, str1
			dw kw_printnl

			; 17: Print "Press a key";
			dw kw_printstrvar, str2

			; 18: Do : Frame : Loop Until Inkey <> 0
do7_t:
			dw kw_frame
			dw kw_inkey, tmp0
			dw kw_cpnevl, tmp0, 0
			dw kw_goto_iffalse_n, do7_t
do7_e:

			; 19: Print
			dw kw_printnl

			; 20: End
			dw kw_stop

; ============================================================
; Jump stubs (code, ROMable)
;   label_go: GOTO label
;   label_gs: GOSUB label, return point -> label_rs (RAM)
;   label_rt: RETURN from label
;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

wh2_c_go:			ld sp, wh2_c
			jp ntc_xn

; ============================================================
; Variables
; ============================================================

var_n:			dw 0
var_i:			dw 0
for1_l:			dw 0
var_j:			dw 0
for4_l:			dw 0
for4_s:			dw 0
var_c:			dw 0
for5_l:			dw 0
tmp0:			dw 0

; ============================================================
; Strings
; ============================================================

str0:			db " ", 0
str1:			db " primes", 0
str2:			db "Press a key", 0

; ============================================================
; Keyword library (rom)
; ============================================================

; Library: ROM - the keyword library is in the NTC LIBRARY ROM (NTCFW.ROM).
; Its routines: this jump block, the numbers made into addresses by the ROM at the start.
; Its variables and constants: fixed addresses (RAM #8800 - #A5EF is the ROM's).
ntc_rj_block:
kw_stop:		jp 1
ntc_xn:		jp 2
kw_goto_iffalse_n:	jp 11
kw_goto_iftrue_n:	jp 13
kw_goto_ifzero_n:	jp 15
kw_forupv_n:	jp 25
kw_next1v_n:	jp 33
kw_forentry_n:	jp 44
kw_fornext_n:	jp 46
kw_ltov:		jp 47
kw_vtov:		jp 48
kw_ztov:		jp 49
kw_inc:		jp 51
kw_mulvv:	jp 60
kw_scplevv:	jp 81
kw_cpnevl:	jp 98
kw_aget:		jp 111
kw_asetl:	jp 117
kw_printstrvar:	jp 129
kw_printint:	jp 131
kw_printnl:	jp 138
kw_inkey:	jp 144
kw_frame:	jp 152
kw_bssinit:	jp 288
NTC_RJ_N	equ 24		; entries
ntc_csp	equ #8800		; ROM data
ntc_nmode	equ #8806		; ROM data
ntc_v_free	equ #8844		; ROM data
ntc_v_romen	equ #884A		; ROM data
ntc_v_romold	equ #884C		; ROM data
ntc_v_stamp	equ #8848		; ROM data
ntc_v_start	equ #8846		; ROM data
			ASSERT ntc_free <= #8800, "Library: ROM - the program and its arrays must end below #8800 (the ROM's RAM)"

; the start: find the ROM in slots 0 - 31, have it patch the jump block. NC = ready;
; C = not there / too old (the message is shown, the caller's ROM selection is back)
ntc_rj_find:
			ld c, 0
			call #B90F		; KL ROM SELECT: B / C = the caller's state and selection
			ld (ntc_rj_old), bc
			ld c, 0
ntc_rj_next:
			push bc
			call #B90F		; KL ROM SELECT: ROM C
			pop bc
			ld a, (#C000)
			cp 1				; a background ROM?
			jr nz, ntc_rj_skip
			ld hl, (#C004)		; its names
			ld a, h
			cp #C0
			jr c, ntc_rj_skip
ntc_rj_name:
			ld a, (hl)
			inc hl
			or a
			jr nz, ntc_rj_name		; to the 0 after the names
			ld de, ntc_rj_sig
			ld b, ntc_rj_sige - ntc_rj_sig
ntc_rj_cmp:
			ld a, (de)
			cp (hl)
			jr nz, ntc_rj_skip
			inc de
			inc hl
			djnz ntc_rj_cmp
			ld e, (hl)
			inc hl
			ld d, (hl)			; its patcher
			ld (ntc_rj_call + 1), de
			ld a, c				; its slot
			ld hl, ntc_rj_block
			ld bc, NTC_RJ_N
ntc_rj_call:
			call 0				; HL = jump block, BC = entries, A = slot; C: DE = a number it hasn't got
			jr c, ntc_rj_lacks
			ld hl, ntc_free
			ld (ntc_v_free), hl
			ld hl, ntc_start
			ld (ntc_v_start), hl
			ld hl, 0
			ld (ntc_v_stamp), hl
			ld a, 0
			ld (ntc_v_romen), a
			ld a, (ntc_rj_old)
			ld (ntc_v_romold), a
			or a				; NC: ready
			ret
ntc_rj_skip:
			inc c
			ld a, c
			cp 32
			jr c, ntc_rj_next
			ld hl, ntc_rj_tnf
			jr ntc_rj_fail
ntc_rj_lacks:
			ld (ntc_rj_num), de
			ld hl, ntc_rj_tlk
ntc_rj_fail:
			push hl
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT: the caller's selection again
			pop hl
			call ntc_rj_puts
			ld hl, ntc_rj_tlk
			or a
			sbc hl, de			; (DE: past the message shown)
			jr nz, ntc_rj_nl
			ld a, (ntc_rj_num + 1)
			call ntc_rj_hex
			ld a, (ntc_rj_num)
			call ntc_rj_hex
ntc_rj_nl:
			ld hl, ntc_rj_tnl
			call ntc_rj_puts
			ei
			call #BB06		; KM WAIT CHAR: a key first (a RUN" program's return resets the machine)
			di
			scf
			ret
ntc_rj_puts:				; HL = text, 0 ends; DE = its start
			ld d, h
			ld e, l
ntc_rj_pl:
			ld a, (hl)
			or a
			ret z
			call #BB5A		; TXT OUTPUT
			inc hl
			jr ntc_rj_pl
ntc_rj_hex:
			push af
			rrca
			rrca
			rrca
			rrca
			call ntc_rj_dig
			pop af
ntc_rj_dig:
			and 15
			add a, #90
			daa
			adc a, #40
			daa
			jp #BB5A
; End: the caller's ROM selection again, then back to the caller
ntc_rj_exit:
			ld bc, (ntc_rj_old)
			call #B918		; KL ROM DESELECT
			ret
ntc_rj_old:		dw 0			; the caller's ROM selection (C) and state (B)
ntc_rj_num:		dw 0
ntc_rj_sig:		db "NTC", 1, "CPCFW", 0	; the ROM's NTC block
ntc_rj_sige:
ntc_rj_tnf:		db "NTC LIBRARY ROM (CPCFW) not found", 0
ntc_rj_tlk:		db "NTC LIBRARY ROM too old: no routine #", 0
ntc_rj_tnl:		db 13, 10, "Press a key", 13, 10, 0

ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bss		equ ntc_end
arr_s		equ ntc_bss + 0		; 2002 bytes
ntc_bss_size	equ 2002
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
			SAVEAMSDOS "E29.BIN", ntc_start, ntc_end - ntc_start, ntc_start